const items = $input.all();

// Agrupamos por session_id
const sessions = {};

for (const item of items) {
  const { session_id, type, content, created_at } = item.json;
  if (!sessions[session_id]) sessions[session_id] = [];

  sessions[session_id].push({
    type,
    content,
    created_at: new Date(created_at)
  });
}

// Ordenamos cada sesión por fecha ASC
for (const id in sessions) {
  sessions[id].sort((a, b) => a.created_at - b.created_at);
}

// Generamos un string único con TODAS las conversaciones
let finalString = "";

for (const sessionId of Object.keys(sessions)) {

  // String de una sola conversación
  const conversationString = sessions[sessionId]
    .map(m => {
      const clean = m.content
        .replace(/Mensaje del usuario:\s*/gi, "")
        .replace(/Fecha de hoy.*$/gms, "")
        .trim();

      return `[${m.type.toUpperCase()}] ${clean}`;
    })
    .join("\n");

  // Agregamos separador entre sesiones
  finalString += 
`===========================
CONVERSACIÓN SESSION_ID: ${sessionId}
===========================

${conversationString}

\n\n`;
}

return [
  {
    json: {
      conversations: finalString.trim()
    }
  }
];
